local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local DialogueChoice = require "actions/DialogueChoice"
local Do = require "actions/Do"
local Wait = require "actions/Wait"
local Ease = require "actions/Ease"
local PlayAudio = require "actions/PlayAudio"
local Spawn = require "actions/Spawn"

local NPC = require "object/NPC"

return function(self)
    if self.scene.objectLookup.VendingMachine.state == NPC.STATE_TOUCHING then
        return Action()
    end

    return BlockPlayer {
        Do(function()
            self.scene.player.hidekeyhints[self] = true
        end),
        MessageBox{message="Sonic: Whoah! {p60}Way past cool!{p60} I played this game when I was kid!"},
        DialogueChoice(
            "Play Feels the Rabbit?",
            {
                {"Yes",
                    function(menu)
                        menu:close()
                        self.isOn = not self.isOn

                        self.scene:run(Spawn(BlockPlayer {
                            Ease(smogLayer, "opacity", self.isOn and 0 or 0.5, 0.5),
                            Do(function() self.scene.player.state = self.isOn and "pose" or "irritated" end),
                            MessageBox{message=self.isOn and "Sonic: Hey, I can actually breath again!" or "Sonic: Why did I do that?", sfx=self.isOn and "levelup" or "error"},
                            Do(function()
                                self.scene.player.state = "idledown"
                                self.scene.player.hidekeyhints[self] = false
                            end)
                        }))
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

