local BlockPlayer = require "actions/BlockPlayer" local MessageBox = require "actions/MessageBox" local DialogueChoice = require "actions/DialogueChoice" local Do = require "actions/Do" local Wait = require "actions/Wait" local Ease = require "actions/Ease" local PlayAudio = require "actions/PlayAudio" local Spawn = require "actions/Spawn"
return function(self) return BlockPlayer { Do(function() self.scene.player.hidekeyhints[self] = true end), MessageBox{message="Sonic: Yo, what is up with this?"}, DialogueChoice( "Will you use the Enertron?", { {"Yes", function(menu) menu:close()
self.scene:run(Spawn(BlockPlayer { Do(function() self.scene.player.x = self.x + 48 self.scene.player.y = self.y + 84 self.scene.player.state = "idledown" for k,v in pairs(GameState.party) do v.hp = v.stats.maxhp v.sp = v.stats.maxsp end end), Wait(1), PlayAudio("sfx", "heal", 1), Wait(0.5), Do(function() self.scene.player.y = self.y + 120 self.scene.player.state = "pose" end), MessageBox{message="HP/SP recovered!", sfx="levelup"}, Wait(0.5), Do(function() self.scene.player.state = "worrieddown" end), MessageBox{message="But you're still hungry."}, Do(function() self.scene.player.state = "idledown" self.scene.player.hidekeyhints[self] = false end) })) end}, {"No", function(menu) menu:close() end} } ) } end

local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local DialogueChoice = require "actions/DialogueChoice"
local Do = require "actions/Do"
local Wait = require "actions/Wait"
local Ease = require "actions/Ease"
local PlayAudio = require "actions/PlayAudio"
local Spawn = require "actions/Spawn"

local NPC = require "object/NPC"

return function(self)
    if self.scene.objectLookup.Enertron.state == NPC.STATE_TOUCHING then
        return Action()
    end

    if self.scene.objectLookup.Arcade.state == NPC.STATE_TOUCHING then
        return Action()
    end

    return BlockPlayer {
        Do(function()
            self.scene.player.hidekeyhints[self] = true
        end),
        DialogueChoice(
            self.isOn and "Turn off the Air Purifier?" or "Turn on the Air Purifier?",
            {
                {"Yes",
                    function(menu)
                        menu:close()
                        self.isOn = not self.isOn

                        local smogLayer = self.scene:findLayer("smog")
                        self.scene:run(Spawn(BlockPlayer {
                            Ease(smogLayer, "opacity", self.isOn and 0 or 0.5, 0.5),
                            Do(function() self.scene.player.state = self.isOn and "pose" or "irritated" end),
                            MessageBox{message=self.isOn and "Sonic: Hey, I can actually breath again!" or "Sonic: Why did I do that?", sfx=self.isOn and "levelup" or "error"},
                            Do(function()
                                self.scene.player.state = "idledown"
                                self.scene.player.hidekeyhints[self] = false
                            end)
                        }))
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

local BlockPlayer = require "actions/BlockPlayer"
local Ease = require "actions/Ease"
local Wait = require "actions/Wait"

return function(self)
    return BlockPlayer {
        Ease(self.scene.camPos, "x", -400, 1),
        Wait(1)
    }
end
